<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model { protected $guarded = []; public function category(){return $this->belongsTo(Category::class);} public function variants(){return $this->hasMany(ProductVariant::class);} public function reviews(){return $this->hasMany(Review::class);} public function getImageUrlAttribute(){return $this->image_path ? asset('storage/'.$this->image_path) : asset('img/product-'.$this->image_index.'.jpg');} }
